create table if not exists announcements (sent_time timestamp(6), communication_policy_id uuid not null, id uuid not null, welcome_center_id uuid not null, primary key (id));
create table if not exists application_settings (using_internet_server boolean not null, usingkiss boolean not null, id uuid not null, aprs_filter varchar(255), digi_path varchar(255), internet_server_address varchar(255), internet_server_passcode varchar(255), internet_server_port varchar(255), internet_server_username varchar(255), kiss_baud_rate varchar(255), kiss_host varchar(255), kiss_init_command1 varchar(255), kiss_init_command2 varchar(255), kiss_port varchar(255), map_tile_url varchar(255), primary key (id));
create table if not exists communication_categories (auto_generated_text boolean not null, system_defined boolean not null, id uuid not null, description varchar(4000), name varchar(255) not null, primary key (id), constraint uk_category_name unique (name));
create table if not exists communication_events (context uuid, id uuid not null, welcome_center_id uuid not null, callsign varchar(255), packet_processor_id varchar(255), type enum ('ENTER_REGION','EXIT_REGION','ON_REQUEST'), primary key (id));
create table if not exists communication_policies (end_time time(6), start_time time(6), category_id uuid not null, id uuid not null, welcome_center_id uuid not null, message_text varchar(4000), communication_event_type enum ('ENTER_REGION','EXIT_REGION','ON_REQUEST'), message_type enum ('BULLETIN','MESSAGE'), primary key (id));
create table if not exists ignore_stations (callsign varchar(10) not null, id uuid not null, primary key (id), constraint uk_ignore_station_callsign unique (callsign));
create table if not exists station_commands (received_time timestamp(6), callsign varchar(10), id uuid not null, welcome_center_id uuid, command varchar(255), type enum ('IGNOREME','INFO','LISTSUBSCRIPTIONS','SUBSCRIBE','UNKNOWN','UNSUBSCRIBE'), primary key (id));
create table if not exists station_messages (sent_time timestamp(6), callsign_from varchar(10), callsign_to varchar(10), id uuid not null, welcome_center_id uuid, content varchar(4000), packet_processor_id varchar(255), message_type enum ('BULLETIN','MESSAGE'), primary key (id));
create table if not exists station_packets (received_time timestamp(6), callsign varchar(10), id uuid not null, command varchar(255), packet_processor_id varchar(255), header clob, primary key (id));
create table if not exists station_positions (created_time timestamp(6), id uuid not null, station_id uuid not null, callsign varchar(255), latitude varchar(255), longitude varchar(255), primary key (id));
create table if not exists stations (callsign varchar(10) not null, id uuid not null, state enum ('MOVING','STATIONARY','UNKNOWN'), primary key (id), constraint uk_station_callsign unique (callsign));
create table if not exists welcome_center_weather_reports (barometric_pressure float(24), humidity float(24), luminosity float(24), temperature float(24), report_time timestamp(6), id uuid not null, callsign varchar(255), latitude varchar(255), longitude varchar(255), primary key (id));
create table if not exists welcome_centers (callsign varchar(10) not null, contact_callsign varchar(10), organization_callsign varchar(10), owner_callsign varchar(10), id uuid not null, description varchar(4000), contact_name varchar(255), latitude varchar(255), longitude varchar(255), name varchar(255), organization_name varchar(255), owner_name varchar(255), symbol_code varchar(255), symbol_id varchar(255), primary key (id), constraint uk_welcome_center_callsign unique (callsign));
create table if not exists welcome_regions (diameter integer, id uuid not null, welcome_center_id uuid, description varchar(4000), bottom_right_latitude varchar(255), bottom_right_longitude varchar(255), center_latitude varchar(255), center_longitude varchar(255), name varchar(255), top_left_latitude varchar(255), top_left_longitude varchar(255), type enum ('CIRCLE','RECTANGLE'), unit enum ('FEET','KILOMETERS','METERS','MILES'), primary key (id));
create index if not exists idx_station_position_station_created on station_positions (station_id, created_time);
